                        tx, ty = p[0], p[1]
                        if isinstance(tx, int) and isinstance(ty, int):
                            targets.append((tx, ty))

    # If targets still empty, fall back to moving toward a corner or center
    if not targets:
        targets.append((0, 0))
        targets.append((1, 1))
        targets.append((-1, -1))

    # Choose a target closest to current position
    best = None
    best_dist = None
    for tx, ty in targets:
        dx = tx - x if isinstance(x, int) else 0
        dy = ty - y if isinstance(y, int) else 0
        dist = abs(dx) + abs(dy)
        if best_dist is None or dist < best_dist:
